{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"New Jersey Security Deposit Law","requirement":"A landlord may not collect a security deposit above one and one-half times one month's rent, must hold the deposit in trust and pay the tenant the interest earned, and must return it with interest less itemized deductions within 30 days after the tenancy ends.","key_value":"1.5 months' rent; yearly deposit increase max 10%","coverage_conditions":"Residential rentals in New Jersey; landlords receiving deposits for 10 or more units may invest in a money market fund or variable-rate New Jersey account.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Account rules differ for landlords receiving deposits for ten or fewer units versus 10 or more units."},"exemptions":"Security deposit provisions do not apply to seasonal use or rental, meaning a term of not more than 125 consecutive days for residential purposes by a person whose permanent residence is elsewhere; the landlord bears the burden of proving seasonal use.","penalty":"Tenant may sue for double the amount of the deposit wrongfully withheld, plus court costs and reasonable attorney's fees.","effective_date":null,"citation":"N.J.S.A. 46:8-21.2","quoted_span":"The maximum-security deposit to be collected by the landlord cannot be more than one and one-half times one month’s rent ( N.J.S.A. 46:8-21.2 ). It can be less. Any additional yearly security deposit increase may not exceed 10% of the current security deposit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"Safe Housing Act security deposit return after domestic violence lease termination","requirement":"When a tenant ends a lease early under the Safe Housing Act, the landlord must make the deposit plus interest available within 15 business days and, within three business days, notify the tenant in writing where and when to collect it.","key_value":"15 business days","coverage_conditions":"Leases terminated before expiration under the Safe Housing Act by victims of domestic violence; the law does not apply to transient or seasonal rentals.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":"Transient or seasonal rentals.","penalty":null,"effective_date":null,"citation":"N.J.S.A. 46:8-9.6","quoted_span":"Within 15 business days after the lease is terminated, the landlord shall make available the return of the tenant’s security deposit, plus any interest earned, to the tenant or the tenant’s agent.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
